with.script:
const issue = context.payload.issue;

// Check if the issue belongs to integration autonomy
const EXCLUDED_PROJECTS = ['Integration autonomy'];

const { node } = await github.graphql(`
  query($issueId: ID!) {
    node(id: $issueId) {
      ... on Issue {
        projectItems(first: 10) {
          nodes {
            project { title }
          }
        }
      }
    }
  }
`, { issueId: issue.node_id });

const projects = (node?.projectItems?.nodes || []).map(n => n.project.title);
const isExcluded = projects.some(p => EXCLUDED_PROJECTS.includes(p));

if (isExcluded) {
  core.info(`Skipping: issue belongs to excluded project (${projects.join(', ')})`);
  core.setOutput('notify', 'false');
  return;
}

const labels = (issue.labels || []).map(l => l.name).join(', ');
const payload = {
  text: `New wizard issue: <${issue.html_url}|${issue.title}>\nBy: ${issue.user.login}\nLabels: ${labels || 'none'}`
};
core.setOutput('notify', 'true');
core.setOutput('payload', JSON.stringify(payload));

steps.run:
set -o pipefail
# Unique per run so a replay never collides with an existing account.
email="${PROBE_EMAIL/@/+probe-${GITHUB_RUN_ID}@}"

node ./dist/index.js provision \
  --email "$email" \
  --region "$REGION" \
  --json > result.json

# A response the wizard can't read is the failure this probe exists to catch,
# so assert on the fields the signup flow actually consumes.
node -e '
  const r = require("./result.json");
  const missing = ["projectApiKey", "host", "projectId"].filter((k) => !r[k]);
  if (missing.length) {
    console.error("provisioning returned no " + missing.join(", "));
    process.exit(1);
  }
  console.log("provisioned project " + r.projectId + " on " + r.host);
'

with.payload:
